-- AID v1.0.0-beta.4 数据库迁移脚本。
-- 可重复执行：补齐隐藏风格字段与查询索引，并只同步初始化库既有的 51 个官方风格。

SET @schema_name = DATABASE();

SELECT COUNT(*) INTO @comic_asset_hidden_exists
FROM information_schema.COLUMNS
WHERE TABLE_SCHEMA = @schema_name
  AND TABLE_NAME = 'aid_comic_asset'
  AND COLUMN_NAME = 'hidden_style_prompt_json';
SET @ddl = IF(
    @comic_asset_hidden_exists = 0,
    'ALTER TABLE `aid_comic_asset` ADD COLUMN `hidden_style_prompt_json` JSON NULL COMMENT ''隐藏风格提示词(character/scene/prop)'' AFTER `prompt_text`',
    'SELECT 1'
);
PREPARE ddl_stmt FROM @ddl;
EXECUTE ddl_stmt;
DEALLOCATE PREPARE ddl_stmt;

SELECT COUNT(*) INTO @user_asset_hidden_exists
FROM information_schema.COLUMNS
WHERE TABLE_SCHEMA = @schema_name
  AND TABLE_NAME = 'aid_user_comic_asset'
  AND COLUMN_NAME = 'hidden_style_prompt_json';
SET @ddl = IF(
    @user_asset_hidden_exists = 0,
    'ALTER TABLE `aid_user_comic_asset` ADD COLUMN `hidden_style_prompt_json` JSON NULL COMMENT ''隐藏风格提示词(character/scene/prop)'' AFTER `prompt_text`',
    'SELECT 1'
);
PREPARE ddl_stmt FROM @ddl;
EXECUTE ddl_stmt;
DEALLOCATE PREPARE ddl_stmt;

SELECT COUNT(*) INTO @project_hidden_exists
FROM information_schema.COLUMNS
WHERE TABLE_SCHEMA = @schema_name
  AND TABLE_NAME = 'aid_comic_project'
  AND COLUMN_NAME = 'hidden_style_prompt_json';
SET @ddl = IF(
    @project_hidden_exists = 0,
    'ALTER TABLE `aid_comic_project` ADD COLUMN `hidden_style_prompt_json` JSON NULL COMMENT ''项目隐藏风格提示词快照(character/scene/prop)'' AFTER `video_style_value`',
    'SELECT 1'
);
PREPARE ddl_stmt FROM @ddl;
EXECUTE ddl_stmt;
DEALLOCATE PREPARE ddl_stmt;

ALTER TABLE `aid_comic_project`
    MODIFY COLUMN `video_style_type` varchar(100) NULL COMMENT '视频风格名称',
    MODIFY COLUMN `video_style_value` text NULL COMMENT '视频风格公开提示词快照';

SELECT COUNT(*) INTO @style_query_index_exists
FROM information_schema.STATISTICS
WHERE TABLE_SCHEMA = @schema_name
  AND TABLE_NAME = 'aid_extract_task'
  AND INDEX_NAME = 'idx_project_task_status_del';
SET @ddl = IF(
    @style_query_index_exists = 0,
    'ALTER TABLE `aid_extract_task` ADD INDEX `idx_project_task_status_del` (`project_id`, `task_type`, `status`, `del_flag`)',
    'SELECT 1'
);
PREPARE ddl_stmt FROM @ddl;
EXECUTE ddl_stmt;
DEALLOCATE PREPARE ddl_stmt;

START TRANSACTION;

-- 旧自定义风格仅在隐藏模板为空时迁移，避免覆盖用户已配置的内容。
UPDATE `aid_user_comic_asset`
SET `hidden_style_prompt_json` = JSON_OBJECT(
        'character', `prompt_text`,
        'scene', '',
        'prop', ''
    ),
    `update_time` = NOW(),
    `update_by` = 'system'
WHERE `asset_type` = 'style'
  AND `prompt_text` IS NOT NULL
  AND TRIM(`prompt_text`) <> ''
  AND `hidden_style_prompt_json` IS NULL
  AND `status` = '0'
  AND `del_flag` = '0';

-- 按初始化库稳定主键同步 51 个官方风格，不导入测试库中的其他扩展风格。
UPDATE `aid_comic_asset`
SET `hidden_style_prompt_json` = CASE `id`
        WHEN 1 THEN CONVERT(FROM_BASE64('') USING utf8mb4)
        WHEN 2 THEN CONVERT(FROM_BASE64('') USING utf8mb4)
        WHEN 3 THEN CONVERT(FROM_BASE64('') USING utf8mb4)
